// Normalize text for matching: lowercase, collapse whitespace
function normalize(text) {
  return text.toLowerCase().replace(/\s+/g, " ").trim();
}

// Get full detail for a line item. Returns an object with description,
// whatYouGet, howItWorks, seoValue, aeoValue — or null if no match.
export function getLineItemDetail(text) {
  const lower = normalize(text);
  for (const d of DETAILS) {
    if (d.match.some((m) => lower.includes(m.toLowerCase()))) {
      return {
        description: d.description,
        whatYouGet: d.whatYouGet,
        howItWorks: d.howItWorks,
        seoValue: d.seoValue,
        aeoValue: d.aeoValue,
        category: d.category,
      };
    }
  }
  return null;
}

// Get just the description string (backward compatible)
export function getLineItemDescription(text) {
  const detail = getLineItemDetail(text);
  return detail ? detail.description : null;
}